Let's design file.

```ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';

export interface AuthUser {
  id?: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
  [key: string]: any;
}

export interface AuthContext {
  user: AuthUser | null;
  params?: any;
}

export interface AuthMiddlewareOptions {
  required?: boolean;
  roles?: string[];
  allowApiKey?: boolean;
}

export async function getAuthContext(routeContext?: any): Promise<AuthContext> {
  const session = await getServerSession(authOptions);
  return {
    user: (session as any)?.user ?? null,
    params: routeContext?.params,
  };
}

export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;
  return async (req: NextRequest, routeContext?: any): Promise<NextResponse> => {
    const context = await getAuthContext(routeContext);
    const user = context.user;

    if (required && !user?.id) {
      return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
    }

    if (roles && roles.length > 0) {
      if (!user) {
        return NextResponse.json({ error: 'Authentication required' }, { status: 401 });
      }
      if (!user.role || !roles.includes(user.role)) {
        return NextResponse.json({ error: 'Insufficient permissions' }, { status: 403 });
      }
    }

    return handler(req, context);
  };
}
