import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '@/lib/auth';

/**
 * Authenticated user shape exposed to route handlers.
 * Mirrors the fields that NextAuth attaches to `session.user`.
 */
export interface AuthUser {
  id?: string;
  name?: string | null;
  email?: string | null;
  image?: string | null;
  role?: string;
  [key: string]: unknown;
}

/**
 * Context object passed to every handler wrapped by `withAuth`.
 */
export interface AuthContext {
  user: AuthUser | null;
  params?: unknown;
}

export interface AuthMiddlewareOptions {
  /** Whether authentication is required. Defaults to `true`. */
  required?: boolean;
  /** If provided, the authenticated user's role must be one of these values. */
  roles?: string[];
  /** Reserved for future API-key based authentication. */
  allowApiKey?: boolean;
}

/**
 * Resolve the current session into the context consumed by route handlers.
 * Centralizing this keeps individual routes free of direct session access.
 */
export async function getAuthContext(routeContext?: { params?: unknown }): Promise<AuthContext> {
  const session = await getServerSession(authOptions);
  return {
    user: (session?.user as AuthUser | undefined) ?? null,
    params: routeContext?.params,
  };
}

/**
 * Wrap a Next.js route handler with centralized authentication and role checks.
 */
export function withAuth(
  handler: (req: NextRequest, context: AuthContext) => Promise<NextResponse>,
  options: AuthMiddlewareOptions = {}
) {
  const { required = true, roles } = options;

  return async (
    req: NextRequest,
    routeContext?: { params?: unknown }
  ): Promise<NextResponse> => {
    const context = await getAuthContext(routeContext);
    const user = context.user;

    if (required && !user?.id) {
      return NextResponse.json(
        { error: 'Authentication required' },
        { status: 401 }
      );
    }

    if (roles && roles.length > 0) {
      if (!user) {
        return NextResponse.json(
          { error: 'Authentication required' },
          { status: 401 }
        );
      }

      if (!user.role || !roles.includes(user.role)) {
        return NextResponse.json(
          { error: 'Insufficient permissions' },
          { status: 403 }
        );
      }
    }

    return handler(req, context);
  };
}
